import { readdir, mkdir } from "node:fs/promises";
import { join } from "node:path";
import { convertFile } from "./convert.mjs";

const input = process.argv[2] ?? "photos";
const output = process.argv[3] ?? "converted";
await mkdir(output, { recursive: true });
for (const entry of await readdir(input, { withFileTypes: true })) {
  if (!entry.isFile() || !/\.png$/i.test(entry.name)) continue;
  try {
    // Keep the original extension in the name to avoid collisions.
    await convertFile(join(input, entry.name), "webp", join(output, `${entry.name}.webp`));
  } catch (error) {
    console.error(error instanceof Error ? error.message : "Conversion failed");
    process.exitCode = 1;
  }
}
